INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(370300, 0, 3703, 0, 0, 0, 'Shattrath City', 'Shattrath, whose name means dwelling of light, was once the capital of the draenei on this world. When the Burning Legion turned the orcs against them, the fiercest battle of that war was fought here, and the city fell. For years it lay in ruin and darkness, until the naaru called the Sha''tar came to Outland to fight the demons and were drawn to these ruins, where a small remnant of the draenei priesthood still held its rites. Those priests, the Aldor, regained their strength, and rebuilding began. Later a host of blood elves sent by Kael''thas marched on the city and instead knelt before the naaru A''dal, becoming the Scryers. Today it rises in northwestern Terokkar Forest, perhaps the one place in Outland with any semblance of safety. A''dal holds the Terrace of Light at its heart, the two rival orders keep their own heights above it, and refugees of every race crowd the Lower City. Portals link it to the capitals of Azeroth, and from here the Sha''tar make war on the Legion and its allies.', 'creature_text 19685 (Khadgar''s Servant tour: dwelling of light, fiercest battle, ruins and darkness, Sha''tar, Aldor, Scryers); quest 10210 description (one place in Outland with any semblance of safety); warcraft.wiki.gg/wiki/Shattrath_City (draenei capital, Terrace of Light, Aldor Rise, Scryer''s Tier, Lower City); DB gameobjects 183317-183327, 187056 (Shattrath portals)'),
(370301, 1, 3703, 1, 0, 0, 'Terrace of Light', 'The Terrace of Light is the heart of Shattrath and the seat of the Sha''tar. In the chamber at its center floats A''dal, leader of the naaru, with Khadgar close at hand, and around the hall stand portals to the capitals of the Alliance and the Horde. Grand Anchorite Almonen preaches here that the Light dwells within each of us as a gift, and General Tiras''alan studies an image of the Sunwell''s defenses beneath the naaru. Spymistress Mehlisah Highcrown speaks for the Lower City, urging that Auchindoun be cleared of the Shadow Council. The Aldor and the Scryers each keep a bank on the terrace''s rim.', 'DB spawns: A''dal 18481 (-1864,5430), Khadgar 18166, Almonen 19216, Tiras''alan 25167, Mehlisah 18893, portals 183317-183327 and 187056 around the chamber; creature_text 19216 (Almonen''s sermon); quest 11550 description (representation of the Sunwell''s defenses below A''dal); npc_text 9615 (Mehlisah); npc_text 10379 (two banks on the rim of the central hub); warcraft.wiki.gg/wiki/Shattrath_City (Terrace of Light, seat of the Sha''tar); game_event_gameobject: Quel''Danas portal 187056 only in Sun''s Reach phase event 105; quests 10091, 10095 objectives (Mehlisah at the Terrace of Light)'),
(370302, 1, 3703, 2, 0, 0, 'Lower City', 'The Lower City is the lowest ring of Shattrath and the home of its refugees. As one of the only safe havens in Outland, the city draws them from every war, past and present: Broken and Lost Ones, sporelings and Mag''har, high elves, dwarves, orcs and human peasants, and arakkoa outcasts who turned from Skettis. Every spare building now houses them; the rogue Lonika Stillblade has even closed her academy. Khadgar warns newcomers to watch for pickpockets. It is a busy market too: Griftah swears by his miraculous amulets, the arakkoa alchemist Lorokeem keeps his strange equipment in the northwest, and battle-mages, one for the Alliance and one for the Horde, send soldiers north to the war for Wintergrasp.', 'creature_text 19685 groups 4 (droves of refugees from all wars); zone_areas: Broken, Lost One, Sporeling, Mag''har, High Elf, Dwarf, Orc and Peasant Refugees, Skettis Outcast, Redeemed Avian in 3899/3703; npc_text 10686 (Lonika Stillblade); creature_text 18166 group 1 (pickpockets in the Lower City); creature_text 19227 (Griftah); npc_text 10696 (Lorokeem, northwest of the lower city); npc_text 10388 (battlemasters on the stairwells); creature 35596, 35597 Wintergrasp Battle-Mages (gossip 14775 on); warcraft.wiki.gg/wiki/Lower_City; creature 35596 Arcanist Iramhir (template 2027, Silver Covenant, Alliance) and 35597 Magistrix Aldessia (template 2123, Sunreavers, Horde), gossip 10666 and 10662 on Wintergrasp, no game_event'),
(370303, 1, 3703, 3, 0, 0, 'World''s End Tavern', 'At the eastern edge of the Lower City stands the World''s End Tavern, where Shaarubo tends the bar and the barmaid Kylene cooks enough to fill the ogre Grok. Its regulars are a strange lot. The mo''arg Sal''salabim drinks away his sorrows, Raliq the Drunk bellows at all comers, and the socialite Haris Pilton holds court with her pet while an ex-socialite lingers close by. Lonika Stillblade waits here for a new home for her rogue academy, and a stranger named Zephyr, who can carry visitors to the Caverns of Time, muses that even time feels different in this broken world. Just outside, Wind Trader Lathrai admits the tavern offers nothing to his kind, though its patrons buy his wares.', 'npc_text 10394 (tavern in the easternmost portion of the lower city); npc_text 11230, 11231 (Kylene, cooking for Grok); quest 10004 (Sal''salabim at the bar, drinking away his sorrows); npc_text 9440, creature_text 18585 (Raliq); creature_template subnames 18756 Socialite, 18762 Haris Pilton''s Pet, 19719 Ex-Socialite; npc_text 9417 (Lathrai); quests 11354, 11364 (Zhareem and Mah''duun bounties); npc_text 12507 and gossip 9205 (Zephyr, Caverns of Time); DB spawns around -1740..-1770, 5130..5200 (all posarea 3703); quests 9979, 10112 (Lathrai outside, near the World''s End Tavern); npc_text 10686 (Lonika, academy closed for now); DB spawns: Lonika 22442 and Zephyr 25967 on the tavern floor (z -37) beside Shaarubo; Lathrai, Zhareem and Mah''duun at street level (z -40), 35 to 40 yards off'),
(370304, 1, 3703, 4, 0, 0, 'Aldor Rise', 'Aldor Rise is the highest tier of Shattrath and the home of the Aldor, the draenei priesthood that kept its rites among the ruins until the naaru came. On its western side stands the Shrine of Unending Light, their most holy temple, where the Light is said to burn strongly enough to cleanse even the foulest fel taint, and where High Priestess Ishanah receives those who join the order. Adyen the Lightwarden keeps watch over the priesthood, vindicators guard the paths, and anchorites and neophytes train among the dwellings. An inn on the southern side offers rest. As a holy site the rise welcomes only the initiated, and those who side with the Scryers find no friends here.', 'warcraft.wiki.gg/wiki/Shattrath_City (Aldor Rise uppermost, shrine west, inn south); creature_text 19685 groups 6, 16 (priesthood in ruins; most holy temple; only the initiated); quest 10420 description (holiest places, fel taint cleansed); quest 10554 (Ishanah in the Shrine of Unending Light); zone_areas 3896: Ishanah, Adyen, Aldor Vindicator, Anchorite, Neophyte, Minalei; quests 10551, 10552 reward texts'),
(370305, 1, 3703, 5, 0, 0, 'Scryer''s Tier', 'Scryer''s Tier is the raised platform where the Scryers make their home, the blood elves who abandoned Kael''thas for the naaru. Arcane guardians and arcanists watch over its walks, and only those initiated with the Scryers are welcome. In the Seer''s Library on its southwestern side sits their leader, Voren''thal the Seer, who means the library to make a seer out of everyone, and beside him Loremaster Skosiris tends a collection he claims outshines even the grand libraries of Silvermoon. An inn on the eastern side, enchanters, merchants and a fence serve the order''s members. The Aldor take little joy in sharing the city with them, for many priests died at the hands of these very magisters.', 'creature_text 19685 groups 13, 15 (dwelling on the platform above, only the initiated; priests slain by the same magisters); warcraft.wiki.gg/wiki/Shattrath_City (Seer''s Library southwest, inn east); npc_text 10178 (Voren''thal); npc_text 14365 (Loremaster Skosiris); zone_areas 3898: Scryer Arcanist, Scryer Arcane Guardian, Innkeeper Haelthol, Lisrythe Bloodwatch <Fence>, enchanters'),
(370306, 2, 3703, 1, 0, 0, 'A''dal', 'A''dal is the leader of the Sha''tar, the naaru who reclaimed Shattrath, and he rules the city from the Terrace of Light. He speaks without words: those who approach feel a soothing light and hear slow chimes in their minds, and with them comes the assurance that they are safe. Khadgar warns visitors not to trouble him with petty questions, for his will alone keeps the city''s enemies from crushing it. Each day he chooses which rival order joins Xi''ri in Shadowmoon Valley, and the armies take his blessing before they march. When a champion returned from Crimson Watch with word of the Crimson Sigil, Illidan''s elite, A''dal foresaw the day their master would answer for his crimes.', 'npc_text 9800; quest 10210 reward text; creature_text 18166 group 0; creature_text 19685 groups 17-19 (Xi''ri, A''dal''s daily decision and blessing); quest 10781 description and reward text; quest 10793 reward text (Crimson Sigil, Illidan''s elite); warcraft.wiki.gg/wiki/A''dal'),
(370307, 2, 3703, 2, 0, 0, 'Khadgar', 'Khadgar was apprentice to Medivh, the Last Guardian, and it was he who learned that his master had been possessed by Sargeras and had opened the Dark Portal; though he honored Medivh, he slew him. After fighting beside Anduin Lothar, he went into Draenor with Turalyon, Alleria, Danath and Kurdran as the Sons of Lothar, and as that world tore apart they shattered the portal behind them. Trapped in Outland, he sensed the Burning Legion closing in, reached into the Great Dark Beyond, and found A''dal and his naaru. He says he convinced them to come. Now he stands by A''dal, swearing he has learned more from A''dal in five months than in all his years among Dalaran''s libraries.', 'npc_text 9876-9881 (Khadgar''s gossip chain); npc_text 9243; quest 10211 description; warcraft.wiki.gg/wiki/Khadgar (pre-Cataclysm)'),
(370308, 2, 3703, 3, 0, 0, 'High Priestess Ishanah', 'Ishanah is the High Priestess of the Aldor, the draenei priests who serve the Sha''tar, and she receives new allies in the Shrine of Unending Light. It was the Aldor who named the naaru Sha''tar, born from light. Her people were charged with guarding the holy sites of this land, and she grieves that so many altars now lie ruined or defiled. Turning refugees away, she says, would be hypocrisy. Of the Scryers she is blunter: she does not like them or their leader''s wild claims of visions of redemption, but it is not for her to question the wisdom of the naaru, and in such times allies must be taken where they are found.', 'npc_text 9457, 9458, 9459 (gossip); quest 10554 (Khadgar sends Aldor allies to her in the Shrine of Unending Light); quest 10021 description (holy sites and altars)'),
(370309, 2, 3703, 4, 0, 0, 'Voren''thal the Seer', 'Voren''thal the Seer was once a close advisor to Prince Kael''thas, until visions warned him that the prince''s path would lead the blood elves to ruin. When Kael sent a regiment to lay waste to Shattrath, Voren''thal was its leader. On the bridge before the Terrace of Light his soldiers laid down their arms, and he strode in to kneel before A''dal, declaring that he had seen the naaru in a vision and that his race''s only hope lay with him. Many of Kael''s finest scholars and magisters followed him. Now he keeps the Seer''s Library on Scryer''s Tier, where truth is brought to light, while his alchemists brew elixirs to sharpen his often clouded visions.', 'quest 10024 description (close advisor, visions); creature_text 19685 groups 8-12 (the defection); npc_text 10178; quest 10553'),
(370310, 2, 3703, 5, 0, 0, 'Adyen the Lightwarden', 'Adyen the Lightwarden is the sword of the Aldor. He describes his duty plainly: first to protect the priesthood at all costs, and second to destroy the enemies of the Light wherever they hide. From Aldor Rise he asks those who would prove themselves to bring him the insignias of the Burning Legion and the Shadow Council, from the lesser marks of Kil''jaeden carried in the Bone Wastes, Nagrand and Blade''s Edge to the marks of Sargeras worn by the Legion''s officers in Netherstorm and Shadowmoon Valley. He reminds them what the Aldor are, keepers of the Light and servants of the naaru, and what stands against them. When the Sunwell called, he sent all the soldiers he could spare.', 'npc_text 10051; quests 10325, 10653 descriptions and reward texts; quest 11481 (via quel_danas.json 408018)'),
(370311, 2, 3703, 6, 0, 0, 'Magistrix Fyalenn', 'Magistrix Fyalenn of the Scryers has no regrets: leaving Kael''thas, she says, was the best thing any of them ever did, for his followers are too blind or too frightened to see where he is leading them. The prince sees the Scryers as a threat to his hold over other blood elves and has tried to crush them time and again, and few sin''dorei fresh from Silvermoon are willing to keep the company Kael now keeps. Scryers and Kael''s armies attack each other on sight. To Fyalenn the only proof of loyalty is fighting, and she asks for the signets of the Firewing and the higher-ranking Sunfury taken from Kael''s soldiers across Outland.', 'npc_text 10153; quests 10412, 10656 descriptions and reward texts'),
(370312, 2, 3703, 7, 0, 0, 'Sha''nir', 'Sha''nir is an Aldor healer who tends the injured refugees laid out in the city''s infirmary. More arrive every day, some so badly hurt it is a wonder they made it. She cares nothing for the politics of the city and takes help from Aldor or Scryer alike; she is so short of hands, she says, that she would not turn away an ogre who knew how to apply a tourniquet. Poison wounds trouble her most, for her antivenom runs low. Beside her rests Zahlia, blinded by a blow to the head, whom Sha''nir hopes to cure with the blood of an ancient basilisk she has known of since she was a youngling.', 'npc_text 9451; quest 10017 description; quest 10020 description and completion text; DB spawns: Sha''nir 18597 (-1606,5292), Zahlia 18652, Injured Refugee 18600 around it; script_waypoint 19685 points 17 to 19 and zone_shattrath_city.cpp npc_kservant (tour stop at Sha''nir)'),
(370313, 2, 3703, 8, 0, 0, 'Rilak the Redeemed', 'Rilak the Redeemed leads the arakkoa who have made a home in the northern Lower City. He speaks of his race without pride: too often, he admits, the arakkoa have turned dark magic to wicked ends, and it was through A''dal that he learned of the Light and of redemption. Skettis marks such outcasts for death, so Rilak watches Terokk''s city closely and shares what he knows with those who would strike at it, and frontier garrisons plagued by arakkoa raids send envoys to him. He grieves for Skywing, one of the redeemed, who went to Veil Shalas to preach the Light and was cursed for it, and he long took the tales of Terokk''s return for legend.', 'quest 10847 description (dark magic, A''dal, Light and redemption); quests 10862, 10863 (envoys from Stonebreaker Hold and the Allerian Stronghold; northern Lower City); quest 10917 description (outcasts marked for death by Skettis); quest 10898 reward text (Skywing); quest 11028 description (Terokk''s return believed mere legend); quest 11024 (ends with Rilak)'),
(370314, 2, 3703, 9, 0, 0, 'Yuula', 'Yuula is the recruitment officer of the Sha''tari Skyguard, and she does her recruiting in Shattrath itself. The Skyguard is sworn to protect the city from the dangers that loom above it, near and far. Her first concern is close to home: the Gordunni ogres of the Barrier Hills to the north, a threat that Shattrath''s soldiers on the ground have struggled to reach, and the riders of the Skyguard are the ones who can. Those who help contain them earn a hearty welcome as an ace and hear of the Skyguard''s greater war beyond the Skethyl Mountains.', 'quest 11096 description and reward text (sworn to protect Shattrath, Gordunni of the Barrier Hills, ground units, ace); quest 11098 description (beyond the Skethyl Mountains; via terokkar.json 351943); creature_template 23449 subname Recruitment Officer, faction 1856; display 21514 gender 1 in creature_model_info'),
(370315, 2, 3703, 10, 0, 0, 'Barthamus', 'Barthamus is a Netherwing drake who waits in the Lower City with six of his kin, Jorus, Malfas, Onyxien, Suraku, Voranaku and Zoya. He calls himself the first of his flight, the abandoned child of a monster. To the ally who rose to highlord among the Dragonmaw in the Netherwing''s service, he owes everything, for that one hero shattered the Dragonmaw''s hold and brought back secrets enough to occupy his brethren for ten lifetimes. In thanks each of his kin offers to bond with the hero and fly them across Outland, though only one may be chosen, and that choice cannot be undone.', 'quest 11108 description and reward text; quests 11109-11114 reward texts; DB spawns: Barthamus and the six drakes in the Lower City (zone_areas 3899); shadowmoon.json 352040 (Among the Dragonmaw, which ends with Barthamus)'),
(370316, 3, 3703, 1, 0, 0, 'City of Light', 'Newcomers to Shattrath soon hear its story. A haggard war veteran sends them to see A''dal, and Khadgar, too busy to guide them himself, summons a servant to lead the way. Shattrath, the servant explains, was the capital of the draenei and fell in the fiercest battle of the orcs'' war against them. It lay dark until the Sha''tar came and found a remnant of the priesthood, the Aldor, keeping their rites in a ruined temple, which now serves as an infirmary. The Aldor grew strong and rebuilding began. Then Kael''thas sent a regiment of blood elves to destroy the city. On the bridge they laid down their arms, and their leader Voren''thal knelt before A''dal. The defectors became the Scryers, though the Aldor, whose priests those same magisters had slain, have never warmed to them. Since then Xi''ri has carried the war to Illidan''s doorstep, and the orders still vie to join him. To serve the Sha''tar, the servant warns, a newcomer must choose between them, and winning one side''s favor costs the other''s.', 'quest 10210 description; quest 10211 description and texts; creature_text 19685 (the whole tour); creature_text 18166 group 1; quests 10551, 10552'),
(370317, 3, 3703, 2, 0, 0, 'The Aldor''s Charge', 'Those who would stand with the Aldor find the priesthood''s work everywhere. In the city, the healer Sha''nir needs venom sacs from the dreadfang spiders of the southeast to make antidotes for refugees who survived the road only to die of their wounds. Outside the walls, High Priestess Ishanah sends her allies east to an arakkoa outpost deliberately built atop three of the Aldor''s sacred altars, carrying a blessed vial to cleanse each one, for the Aldor are keepers of the Light and cannot forsake their charge even now. In the Shrine of Unending Light she turns fel armaments taken from demons to dust. From Adyen the Lightwarden comes the war itself: the insignias of Kil''jaeden and of Sargeras, stripped from the Legion and the Shadow Council across Outland, each mark a measure of the order''s trust. The Aldor''s reach goes further still, to the anchorites under Exarch Orelis watching Kael''thas in Netherstorm.', 'quests 10017, 10019 descriptions and reward texts; quest 10021 description and reward text; quests 10420, 10421; quests 10325, 10653; quest 11038 description'),
(370318, 3, 3703, 3, 0, 0, 'The Seer''s Visions', 'The Scryers serve the naaru by seeing what others cannot. Voren''thal''s visions are vague and unfocused, so his alchemists brew an elixir to sharpen them, and Arcanist Adyria, whose ethereal supplier has failed her, sends any willing helper after the eyes of dampscale basilisks in the rocky lands of Terokkar; those visions, she says, may one day decide the fate of their race. The order''s war is fought in the open as well. Magistrix Fyalenn demands the signets of Kael''s Firewing soldiers and of his higher-ranking Sunfury as proof of loyalty, since the prince''s armies and the Scryers strike at each other on sight. Voren''thal himself seeks arcane tomes, most often carried by Kael''s blood elves, and condenses each one''s power into a single rune with a clear mind. His spies reach far, too: Spymaster Thalodien''s team in Netherstorm has found something of great importance and asked for reinforcements.', 'quests 10024, 10025 descriptions and reward texts; quests 10412, 10656; quests 10416, 10419; quest 11039 description'),
(370319, 3, 3703, 4, 0, 0, 'Lives in the Lower City', 'Not every tale in Shattrath is one of war. In the Lower City, a boy named Seth, far from his home in Lakeshire, watches the Aldor rebuild the walls and decides they work far faster than old Foreman Oslow ever did; he misses fishing for eels at a lake to the northeast, but his mother says it is too dangerous now. Nearby the arakkoa outcast Vekax cannot set foot outside the walls, for Skettis has marked him for death, so he pays in treasure for the feathers of its servants as proof that the outcasts will not take their punishment lying down. And the fishmonger Oloraak frets over his friend Isfar, who escaped the Sethekk Halls once and has gone back alone to free his sister, ignoring every plea to stay safe in the city.', 'npc_text 9486 (Seth); quest 10037 description and reward text; quests 10917, 10918; quest 10180 description and reward text'),
(370320, 3, 3703, 5, 0, 0, 'The Trials of the Naaru', 'When the ata''mal crystal reached A''dal from Nexus-Prince Haramad, the naaru knew it at once: Spirit''s Song, left by Velen with his people before his ill-fated mission to the Exodar. Perhaps the Prophet foresaw that it would be lost and returned this way. Haramad had hidden a message inside it, how to make the key to Tempest Keep''s Arcatraz from two shards held in the Botanica and the Mechanar. A''dal forged them into one, and soon needed it, for Kael''s warden had failed and Harbinger Skyriss, a servant of the Old Gods, was breaking free. Khadgar brought graver news: Kael''thas had learned of the Cipher of Damnation, and should he use it, what little is left of this world might collapse. Tempest Keep is a naaru creation, A''dal answered, and its way had always been theirs to open, but only the proven may enter. He set four trials: mercy, saving prisoners from Kargath''s executioner; strength, against Warlord Kalithresh and Murmur; tenacity, rescuing the hapless gnome Millhouse Manastorm; and last, the death of Magtheridon.', 'quest 10280 description and reward text; quests 10704, 10882 descriptions and reward texts; quest 10883 description and reward text; quests 10884, 10885, 10886, 10888, 13430'),
(370321, 3, 3703, 6, 0, 0, 'Akama''s Promise', 'With the Medallion of Karabor whole at last, Akama would not keep it, fearing that years so near to evil had weakened him. He sent it to A''dal as his promise to its bearer that he would stand beside them when Illidan was faced, and as the medallion vanished into the naaru''s light, its bearer glimpsed Akama and Maiev fighting their way out of the Warden''s Cage with a shadowy ally beside them. The plan was nearly lost. Seer Olum, freed from naga torturers, warned that Illidan had learned of him, and Olum gave his life to keep the secret. To lull the Betrayer, Akama''s ally, cloaked as an Ashtongue, slew Kael''s phoenix Al''ar at Illidan''s command, then went into the past at the Caverns of Time for the phylactery of Rage Winterchill. With it Akama could reclaim his own soul, long held hostage in the Black Temple. A''dal showed the rest: Xi''ri''s army of Aldor and Scryers storming the temple''s approach to cover Akama and Maiev, and the medallion returned, empowered, as the key to the temple.', 'quests 10708, 10944, 10946, 10947, 10948, 10949, 10985 descriptions and reward texts'),
(370322, 3, 3703, 7, 0, 0, 'The Offensive in Outland', 'While the Shattered Sun Offensive fights on Quel''Danas, its officers in Shattrath keep the war fed from Outland. Emissary Mordin collects nether residue, found by herbalists, miners and skinners across Outland, for oils that colleagues in Stormwind make to harden the troops'' blades and armor; no contribution, he says, is too small. Lord Torvos has learned that Kael''thas means to draw strength away from the Sunwell by ordering the Sunfury of Netherstorm to strike the Offensive''s Outland operations, and he wants their attack plans seized. Harbinger Haronem, under orders to investigate anything that might help, grudgingly sends volunteers to the Spirit Fields of Nagrand with goggles to take readings of strange distortions, all at the insistence of the gnome Whirligig Wafflefry, who is busy hawking gadgets derived from the Offensive''s military inventions.', 'quests 11875, 11877, 11880 descriptions and reward texts; creature_text 25885, 19475; quel_danas.json 408002, 408019 (portal told there)');
